k = int(input())
L = list(map(int, input().split()))
from collections import Counter
c = Counter(x for x in L if x)
code = 0
start = {}
for l in range(1, max(L) + 1):
    code = (code + c.get(l - 1, 0) * (l > 1)) << 1
    start[l] = code
used = {}
for i, l in enumerate(L):
    if l:
        v = start[l] + used.get(l, 0)
        used[l] = used.get(l, 0) + 1
        print(str(i) + " " + format(v, "0" + str(l) + "b"))

